   769	\begin{definition}[Weil divisors]
   770	\label{def:II-6-weil}
   771	\source{hartshorne-algebraic-geometry:II.6}
   772	On a Noetherian integral scheme regular in codimension one, a prime divisor is an integral closed
   773	subscheme of codimension one. A Weil divisor is a finite sum $D=\sum n_Y Y$. The local ring at the
   774	generic point of $Y$ is a DVR, giving $v_Y:K(X)^*\to\mathbb Z$.
   775	\end{definition}
   776	
   777	\begin{proposition}[Principal divisors]
   778	\label{prop:II-6-1}
   779	\source{hartshorne-algebraic-geometry:II.6.1}
   780	\dcref{II.6.1}
   781	For $f\in K(X)^*$, $(f)=\sum_Yv_Y(f)Y$ has finite support. Principal divisors form a subgroup of Weil
   782	divisors.
   783	\end{proposition}
   784	\begin{proof}
   785	On an affine where $f$ is regular, positive valuations occur only at components of $V(f)$; apply the same
   786	argument to $f^{-1}$ on an affine where it is regular. The valuation identity
   787	$v_Y(fg)=v_Y(f)+v_Y(g)$ proves additivity.
   788	\end{proof}
   789	
   790	\begin{definition}[Linear equivalence and class group]
   791	\label{def:II-6-class}
   792	\source{hartshorne-algebraic-geometry:II.6}
   793	$D\sim D'$ when $D-D'=(f)$. The class group is $\operatorname{Cl}X=\operatorname{Div}X/\operatorname{Prin}X$.
   794	\end{definition}
   795	
   796	\begin{theorem}[Factoriality and the divisor class group]
   797	\label{thm:II-6-2}
   798	\source{hartshorne-algebraic-geometry:II.6.2}
   799	\dcref{II.6.2}
   800	Let $A$ be a noetherian domain and $X=\operatorname{Spec}A$.  Then $A$ is a
   801	unique factorization domain if and only if $X$ is normal and $\operatorname{Cl}X=0$.
   802	\end{theorem}
   803	\begin{proof}
   804	A UFD is integrally closed, hence $X$ is normal.  If every height-one prime is principal, every
   805	prime divisor is principal and $\operatorname{Cl}X=0$.  Conversely, if $X$ is normal and its class
   806	group is zero, a height-one prime divisor is linearly equivalent to zero, hence is the divisor of
   807	an element of $K(X)^*$; valuation one at that prime and nonnegative valuations elsewhere show that
   808	the element lies in $A$ and generates the prime.  The height-one criterion for a noetherian domain
   809	then gives factoriality.
   810	\end{proof}
