   835	\begin{proposition}[Divisors on projective space]
   836	\label{prop:II-6-4}
   837	\source{hartshorne-algebraic-geometry:II.6.4}
   838	\dcref{II.6.4}
   839	For $n\geq1$, every divisor on $\mathbb P^n$ is linearly equivalent to a unique multiple of a
   840	hyperplane; hence $\operatorname{Cl}(\mathbb P^n)\simeq\mathbb Z$ generated by a hyperplane.
   841	\end{proposition}
   842	\begin{proof}
   843	On the standard affine cover, clearing denominators shows that a divisor of degree zero is principal;
   844	the degree map sends a hyperplane to $1$ and detects the unique multiple.
   845	\end{proof}
