   847	\begin{proposition}[Restriction of divisors]
   848	\label{prop:II-6-5}
   849	\source{hartshorne-algebraic-geometry:II.6.5}
   850	\dcref{II.6.5}
   851	If $Y$ is a proper closed subset of a noetherian integral scheme $X$, restriction induces an exact
   852	sequence $\operatorname{Div}_Y(X)\to\operatorname{Cl}(X)\to\operatorname{Cl}(X\setminus Y)\to0$.
   853	\end{proposition}
   854	\begin{proof}
   855	A divisor on the open complement closes to a divisor on $X$, and changing the closure changes it by
   856	a divisor supported on $Y$; principal divisors restrict to principal divisors.
